  let found=JSON.parse(localStorage.getItem('find-the-squares-found')||'{}'), iceActivated=JSON.parse(localStorage.getItem('find-the-squares-ice-buttons')||'[false,false,false]'), tab='all', camera={x:0,y:0}, last=0, toastTimer,inOcean=false,inFactory=false,inIce=false,passwordCooldown=0,insaneCooldown=0;
  const $=s=>document.querySelector(s), grid=$('#catalogGrid'), backdrop=$('#backdrop'), confirm=$('#confirmBackdrop'), mapCanvas=$('#mapCanvas'),mapCtx=mapCanvas.getContext('2d'),miniMap=$('#miniMap'),mapButton=$('#mapButton');
  function save(){localStorage.setItem('find-the-squares-found',JSON.stringify(found));localStorage.setItem('find-the-squares-ice-buttons',JSON.stringify(iceActivated))} function count(){return Object.keys(found).length}
  function updateUI(){let n=count(),total=squares.length;$('#progressText').textContent=`${n} / ${total}`;$('#meterFill').style.width=`${n/total*100}%`;$('#catalogSummary').textContent=`${n} of ${total} squares discovered`;renderCatalog()}
  function showToast(s){const t=$('#toast');t.innerHTML=`<span style="color:${s.color}">◆</span> ${s.name} found!`;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
  function currentBiome(){return inIce?biomes[6]:inFactory?biomes[5]:inOcean?biomes[4]:biomes.find(b=>b.range&&player.x>=b.range[0]&&player.x<b.range[1])||biomes[3]}
  function renderCatalog(){const groups=tab==='all'?biomes:biomes.filter(b=>b.id===tab);grid.innerHTML=groups.flatMap(b=>squares.filter(s=>s.biome===b.id).map(s=>{let f=found[s.id];return `<article class="square-card ${f?'':'missing'}"><div class="square-icon" style="background:${s.color}"></div><div><h3>${f?s.name:'Unknown Square'}</h3><p>${f?b.name:s.hint}</p><span class="tier tier-${s.tier.toLowerCase()}">${s.tier}</span>${f?`<span class="found-date">FOUND ${f}</span>`:''}</div></article>`})).join('');$('#catalogTabs').innerHTML=[['all','All squares'],...biomes.map(b=>[b.id,b.name])].map(([id,label])=>`<button class="${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" data-tab="${id}">${label}</button>`).join('');$('#catalogTabs').querySelectorAll('button').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;renderCatalog()})}
