  function loop(t){let dt=Math.min(.035,(t-last)/1000||0);last=t,activeW=inIce?ICE_W:inFactory?FACTORY_W:inOcean?OCEAN_W:W,activeH=inIce?ICE_H:inFactory?FACTORY_H:inOcean?OCEAN_H:H;if(backdrop.hidden&&confirm.hidden){let dx=(keys.d||keys.arrowright||touch.right?1:0)-(keys.a||keys.arrowleft||touch.left?1:0),dy=(keys.s||keys.arrowdown||touch.down?1:0)-(keys.w||keys.arrowup||touch.up?1:0);if(dx||dy){let m=Math.hypot(dx,dy),nx=Math.max(25,Math.min(activeW-25,player.x+dx/m*player.speed*dt)),ny=Math.max(25,Math.min(activeH-25,player.y+dy/m*player.speed*dt));if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny}if(!inOcean&&!inFactory&&!inIce&&Math.hypot(player.x-hiddenPortal.x,player.y-hiddenPortal.y)<hiddenPortal.r){inOcean=true;player.x=oceanPortal.x+100;player.y=oceanPortal.y;showToast({name:'The hidden portal carries you to the ocean',color:'#9edfff'})}else if(!inOcean&&!inFactory&&!inIce&&Math.hypot(player.x-icePortal.x,player.y-icePortal.y)<icePortal.r){inIce=true;player.x=iceReturnPortal.x+105;player.y=iceReturnPortal.y;showToast({name:'A mountain fissure opens into Frostveil Ice Caves',color:'#bdf8ff'})}else if(inOcean&&Math.hypot(player.x-oilPortal.x,player.y-oilPortal.y)<oilPortal.r){inOcean=false;inFactory=true;player.x=factoryPortal.x+100;player.y=factoryPortal.y;showToast({name:'The oil rig portal opens into Ironworks Factory',color:'#ffbd62'})}else if(inFactory&&Math.hypot(player.x-factoryPortal.x,player.y-factoryPortal.y)<factoryPortal.r){inFactory=false;inOcean=true;player.x=oilPortal.x+100;player.y=oilPortal.y;showToast({name:'You return to the oil rig',color:'#ffbd62'})}else if(inIce&&Math.hypot(player.x-iceReturnPortal.x,player.y-iceReturnPortal.y)<iceReturnPortal.r){inIce=false;player.x=icePortal.x+95;player.y=icePortal.y;showToast({name:'You return to the snow mountain',color:'#bdf8ff'})}else if(inOcean&&Math.hypot(player.x-oceanPortal.x,player.y-oceanPortal.y)<oceanPortal.r){inOcean=false;player.x=hiddenPortal.x-95;player.y=hiddenPortal.y;showToast({name:'You return to Glimmerdeep Caves',color:'#bd83ff'})}if(inIce)iceButtons.forEach((b,i)=>{if(!iceActivated[i]&&Math.hypot(player.x-b.x,player.y-b.y)<42){iceActivated[i]=true;save();showToast({name:`Ice button ${b.label} activated (${iceActivated.filter(Boolean).length}/3)`,color:'#98ffb4'})}});squares.filter(s=>s.biome===currentBiome().id).forEach(s=>{if(!found[s.id]&&Math.hypot(player.x-s.x,player.y-s.y)<38){if(s.tier==='Insane'&&inIce){if(iceActivated.every(Boolean)){found[s.id]=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});save();updateUI();showToast(s)}else if(Date.now()>insaneCooldown){insaneCooldown=Date.now()+1800;showToast({name:`The seal needs all three ice buttons (${iceActivated.filter(Boolean).length}/3)`,color:'#be8cff'})}}else if(s.tier==='Insane'){if(Date.now()>passwordCooldown){passwordCooldown=Date.now()+1200;let code=window.prompt('CONTROL CONSOLE LOCKED: Enter the four-digit access code');if(code==='6217'){found[s.id]=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});save();updateUI();showToast(s)}else showToast({name:'Access denied — find the mainland clue',color:'#ff667c'})}}else{found[s.id]=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});save();updateUI();showToast(s)}}})}let rect=canvas.getBoundingClientRect();camera.x=Math.max(0,Math.min(activeW-rect.width,player.x-rect.width/2));camera.y=Math.max(0,Math.min(activeH-rect.height,player.y-rect.height/2));drawScene(rect.width,rect.height);let b=currentBiome();$('#biomePill').textContent=b.name;$('#biomePill').style.background=b.dark+'e6';requestAnimationFrame(loop)}updateUI();requestAnimationFrame(loop);
